const html = $json.body || '';
const htmlLower = html.toLowerCase();

// Very strict "NO OFFERS" detection based on the real page text
// Current page includes "Keine Angebote" and "leider haben wir aktuell keine freien Plätze".
const noOffersByText =
  htmlLower.includes('keine angebote') ||
  htmlLower.includes('leider haben wir aktuell keine freien plätze') ||
  htmlLower.includes('schade - leider haben wir aktuell keine freien plätze');

// Extract ONLY real offer detail links (strict allow-list)
// Must be under /wohnen/aktuelle-wohnangebote/...
const hrefRegex = /href\s*=\s*"([^"]+)"/gi;
const found = new Set();
let m;

while ((m = hrefRegex.exec(html)) !== null) {
  let href = m[1];
  if (href.startsWith('/')) href = 'https://www.stwdo.de' + href;

  const isOfferDetail =
    href.startsWith('https://www.stwdo.de/wohnen/aktuelle-wohnangebote/') &&
    href !== 'https://www.stwdo.de/wohnen/aktuelle-wohnangebote/' &&
    href !== 'https://www.stwdo.de/wohnen/aktuelle-wohnangebote';

  if (isOfferDetail) found.add(href);
}

const offers = Array.from(found).sort();

// Static memory (Code node v2)
const data = $getWorkflowStaticData('global');
if (!Array.isArray(data.prevOffers)) data.prevOffers = [];
const prevOffers = data.prevOffers;

// If page says NO offers, reset memory and DO NOT notify.
if (noOffersByText) {
  data.prevOffers = [];
  return [{
    json: {
      notify: false,
      message: '',
      noOffersByText,
      offersCount: offers.length,
      offers,
      newOffers: []
    }
  }];
}

// If page does NOT say NO offers, only notify when we actually found offer detail links.
const newOffers = offers.filter(u => !prevOffers.includes(u));

let message = '';
if (offers.length > 0 && (newOffers.length > 0 || prevOffers.length === 0)) {
  message =
    `🏠 *StwDo dorm offers detected!*\n\n` +
    `New offers (${newOffers.length}):\n- ${newOffers.join('\n- ')}\n\n` +
    `All extracted offers (${offers.length}):\n- ${offers.join('\n- ')}\n\n` +
    `Main page: https://www.stwdo.de/wohnen/aktuelle-wohnangebote`;
}

// Update stored offers when we extracted something
if (offers.length > 0) data.prevOffers = offers;

const notify = message.trim().length > 0;

return [{
  json: {
    notify,
    message,
    noOffersByText,
    offersCount: offers.length,
    newOffersCount: newOffers.length,
    offers,
    newOffers
  }
}];
